    }
}



public class FfiConverterBoolean: FfiConverter<bool, sbyte> {
    public static FfiConverterBoolean INSTANCE = new FfiConverterBoolean();

    public override bool Lift(sbyte value) {
        return value != 0;
    }

    public override bool Read(BigEndianStream stream) {
        return Lift(stream.ReadSByte());
    }

    public override sbyte Lower(bool value) {
        return value ? (sbyte)1 : (sbyte)0;
    }

    public override int AllocationSize(bool value) {
        return (sbyte)1;
    }

    public override void Write(bool value, BigEndianStream stream) {
        stream.WriteSByte(Lower(value));
    }
}



public class FfiConverterString: FfiConverter<string, RustBuffer> {
    public static FfiConverterString INSTANCE = new FfiConverterString();

    // Note: we don't inherit from FfiConverterRustBuffer, because we use a
    // special encoding when lowering/lifting.  We can use `RustBuffer.len` to
    // store our length and avoid writing it out to the buffer.
    public override string Lift(RustBuffer value) {
        try {
            var bytes = value.AsStream().ReadBytes(Convert.ToInt32(value.len));
            return System.Text.Encoding.UTF8.GetString(bytes);
        } finally {
            RustBuffer.Free(value);
        }
    }

    public override string Read(BigEndianStream stream) {
        var length = stream.ReadInt();
        var bytes = stream.ReadBytes(length);
        return System.Text.Encoding.UTF8.GetString(bytes);
    }

    public override RustBuffer Lower(string value) {
        var bytes = System.Text.Encoding.UTF8.GetBytes(value);
        var rbuf = RustBuffer.Alloc(bytes.Length);
        rbuf.AsWriteableStream().WriteBytes(bytes);
        return rbuf;
    }

    // TODO(CS)
    // We aren't sure exactly how many bytes our string will be once it's UTF-8
    // encoded.  Allocate 3 bytes per unicode codepoint which will always be
    // enough.
    public override int AllocationSize(string value) {
        const int sizeForLength = 4;
        var sizeForString = System.Text.Encoding.UTF8.GetByteCount(value);
        return sizeForLength + sizeForString;
    }

    public override void Write(string value, BigEndianStream stream) {
        var bytes = System.Text.Encoding.UTF8.GetBytes(value);
        stream.WriteInt(bytes.Length);
        stream.WriteBytes(bytes);
    }
}




public class FfiConverterByteArray: FfiConverterRustBuffer<byte[]> {
    public static FfiConverterByteArray INSTANCE = new FfiConverterByteArray();

    public override byte[] Read(BigEndianStream stream) {
        var length = stream.ReadInt();
        return stream.ReadBytes(length);
    }

    public override int AllocationSize(byte[] value) {
        return 4 + value.Length;
    }

    public override void Write(byte[] value, BigEndianStream stream) {
        stream.WriteInt(value.Length);
        stream.WriteBytes(value);
    }
}



/// <summary>
/// Represents a browser instance (e.g., Chrome or Edge).
/// </summary>
public interface IBrowser {
    /// <summary>
    /// Returns the plugin audit log as a JSON array (no secrets are recorded).
    /// </summary>
    string AuditLog();
    /// <summary>
    /// Verifies the integrity of the append-only plugin audit log.
    /// </summary>
    bool AuditVerify();
    /// <summary>
    /// Names of all compiled-in first-party plugins (the catalog).
    /// </summary>
    string[] AvailablePlugins();
    /// <summary>
    /// Returns the browser context ids as a JSON array.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> BrowserContexts();
    /// <summary>
    /// Returns the browser version info as JSON.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> Capabilities();
    /// <summary>
    /// Closes the browser and kills the process.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task Close();
    /// <summary>
    /// Returns all browser cookies as a JSON array.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> Cookies();
    /// <summary>
    /// Deletes cookies with the given name.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task DeleteCookie(string @name);
    /// <summary>
    /// Returns the registered event names.
    /// </summary>
    Task<string[]> EventNames();
    /// <summary>
    /// Grants permissions (JSON array) to an origin.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task GrantPermissions(string @origin, string @permissionsJson);
    /// <summary>
    /// Whether the underlying connection is alive.
    /// </summary>
    Task<bool> IsConnected();
    /// <summary>
    /// Whether an event name is registered.
    /// </summary>
    Task<bool> ListensTo(string @eventName);
    /// <summary>
    /// Loads a third-party plugin. Not supported in this phase.
    ///
    /// The sandboxed, out-of-process runner required for untrusted plugins does
    /// not exist yet, so this always refuses rather than executing unknown code.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    string LoadPlugin(string @path);
    /// <summary>
    /// Creates a new (incognito) browser context and returns its id.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> NewContext();
    /// <exception cref="XcelerateException"></exception>
    Task<Page> NewPage(string @url);
    /// <summary>
    /// Registers interest in a root-session CDP event.
    /// </summary>
    Task On(string @eventName);
    /// <summary>
    /// Alias for [`Browser::on`].
    /// </summary>
    Task Once(string @eventName);
    /// <summary>
    /// Returns a handle to an enabled plugin so its ops can be invoked.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    PluginHandle Plugin(string @name);
    /// <summary>
    /// Names of the plugins currently enabled on this browser.
    /// </summary>
    string[] PluginNames();
    /// <summary>
    /// Removes every registered listener.
    /// </summary>
    Task RemoveAllListeners();
    /// <summary>
    /// Removes a single registered listener.
    /// </summary>
    Task RemoveListener(string @eventName);
    /// <summary>
    /// Resets all permission overrides.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task ResetPermissions();
    /// <summary>
    /// Sets a cookie from a JSON object.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task SetCookie(string @cookieJson);
    /// <summary>
    /// Sets the download directory for the browser.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task SetDownloadBehavior(string @path);
    /// <summary>
    /// Starts CDP tracing.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task StartTracing();
    /// <summary>
    /// Stops CDP tracing.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task StopTracing();
    /// <summary>
    /// Returns the current targets as a JSON array (`Target.getTargets`).
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> Targets();
    /// <summary>
    /// Enables a compiled-in first-party plugin at runtime.
    ///
    /// Launch-time contributions (such as binary patching) only take effect if
    /// the plugin was enabled before the browser launched; enabling a plugin
    /// afterwards applies its runtime hooks to pages created from now on. This
    /// is audited as a runtime enable. Unknown or third-party names are refused.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task UsePlugin(string @name);
    /// <summary>
    /// Returns the browser's user agent.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> UserAgent();
    /// <summary>
    /// Returns the browser version information.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> Version();
    /// <summary>
    /// Waits for the next root-session CDP event named `event_name`.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> WaitForEvent(string @eventName, ulong @timeoutMs);
    /// <summary>
    /// [`Browser::wait_for_event`] with the default 30s timeout.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> WaitForEventDefault(string @eventName);
    /// <summary>
    /// The WebSocket endpoint Chrome was launched with.
    /// </summary>
    string WsEndpoint();
}
/// <summary>
/// Represents a browser instance (e.g., Chrome or Edge).
/// </summary>
public class Browser : IBrowser, IDisposable {
    protected ulong pointer;
    private int _wasDestroyed = 0;
    private long _callCounter = 1;

    public Browser(ulong pointer) {
        this.pointer = pointer;
    }

    ~Browser() {
        Destroy();
    }

    protected void FreeRustArcPtr() {
        _UniffiHelpers.RustCall((ref UniffiRustCallStatus status) => {
            _UniFFILib.uniffi_xcelerate_fn_free_browser(this.pointer, ref status);
        });
    }

    protected ulong CloneRustArcPtr() {
        return _UniffiHelpers.RustCall((ref UniffiRustCallStatus status) => {
            return _UniFFILib.uniffi_xcelerate_fn_clone_browser(this.pointer, ref status);
        });
    }

    public void Destroy()
    {
        // Only allow a single call to this method.
        if (Interlocked.CompareExchange(ref _wasDestroyed, 1, 0) == 0)
        {
            // This decrement always matches the initial count of 1 given at creation time.
            if (Interlocked.Decrement(ref _callCounter) == 0)
            {
                FreeRustArcPtr();
            }
        }
    }

    public void Dispose()
    {
        Destroy();
        GC.SuppressFinalize(this); // Suppress finalization to avoid unnecessary GC overhead.
    }

    private void IncrementCallCounter() 
    {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        long count;
        do
        {
            count = Interlocked.Read(ref _callCounter);
            if (count == 0L) throw new System.ObjectDisposedException(String.Format("'{0}' object has already been destroyed", this.GetType().Name));
            if (count == long.MaxValue) throw new System.OverflowException(String.Format("'{0}' call counter would overflow", this.GetType().Name));

        } while (Interlocked.CompareExchange(ref _callCounter, count + 1, count) != count);
    }

    private void DecrementCallCounter() 
    {
        // This decrement always matches the increment we performed above.
        if (Interlocked.Decrement(ref _callCounter) == 0) {
            FreeRustArcPtr();
        }
    }

    internal void CallWithPointer(Action<ulong> action)
    {
        IncrementCallCounter();
        try {
            action(CloneRustArcPtr());
        }
        finally {
            DecrementCallCounter();
        }
    }

    internal T CallWithPointer<T>(Func<ulong, T> func)
    {   
        IncrementCallCounter();
        try {
            return func(CloneRustArcPtr());
        }
        finally {
            DecrementCallCounter();
        }
    }

    
