public class FfiConverterTypeBrowser: FfiConverter<Browser, ulong> {
    public static FfiConverterTypeBrowser INSTANCE = new FfiConverterTypeBrowser();


    public override ulong Lower(Browser value) {
        return value.CallWithPointer(thisPtr => thisPtr);
    }

    public override Browser Lift(ulong value) {
        return new Browser(value);
    }

    public override Browser Read(BigEndianStream stream) {
        return Lift(stream.ReadULong());
    }

    public override int AllocationSize(Browser value) {
        return 8;
    }

    public override void Write(Browser value, BigEndianStream stream) {
        stream.WriteULong(Lower(value));
    }
}



/// <summary>
/// Represents an HTML element in the DOM.
/// </summary>
public interface IElement {
    /// <summary>
    /// Returns the value of a specific attribute.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string?> Attribute(string @name);
    /// <summary>
    /// Like [`Element::call_json`] but coerces the result to a bool.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<bool> CallBool(string @function, string @argsJson);
    /// <summary>
    /// Calls a JS function on this element with JSON-encoded arguments.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> CallJson(string @function, string @argsJson);
    /// <summary>
    /// Runs a JS function against the first descendant matching `selector`.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> CallOnSelector(string @selector, string @expression);
    /// <summary>
    /// Runs a JS function against every descendant matching `selector`.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> CallOnSelectorAll(string @selector, string @expression);
    /// <summary>
    /// Like [`Element::call_json`] but coerces the result to a string.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> CallString(string @function, string @argsJson);
    /// <summary>
    /// Clicks the element.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element> Click();
    /// <summary>
    /// Clicks the element using realistic mouse movement and CDP input events.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element> ClickStealth();
    /// <summary>
    /// Number of elements this handle represents (always 1).
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<long> Count();
    /// <summary>
    /// Releases the underlying remote object handle.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task Release();
    /// <summary>
    /// Calls a function on this element and coerces the result to a bool.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<bool> EvaluateBool(string @function);
    /// <summary>
    /// Calls a JS function on this element and returns the resulting node.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element> EvaluateHandle(string @function);
    /// <summary>
    /// Calls a function on this element; the result is returned as JSON text.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> EvaluateJson(string @function);
    /// <summary>
    /// Calls a function on this element and coerces the result to a string.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> EvaluateString(string @function);
    /// <summary>
    /// Focuses the element.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element> Focus();
    /// <summary>
    /// Finds a descendant form control by its `<label>` text.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element> GetByLabel(string @label);
    /// <summary>
    /// Finds a descendant by ARIA role.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element> GetByRole(string @role);
    /// <summary>
    /// Finds a descendant whose text contains `text`.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element> GetByText(string @text);
    /// <summary>
    /// Returns this element's enumerable properties as a JSON object.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> GetProperties();
    /// <summary>
    /// Hovers over the element.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element> Hover();
    /// <summary>
    /// Hovers over the element using realistic mouse movement.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element> HoverStealth();
    /// <summary>
    /// Returns the inner HTML of the element.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> InnerHtml();
    /// <summary>
    /// Focuses the element and presses a key.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task Press(string @key);
    /// <summary>
    /// Returns the first descendant matching `selector` as an [`Element`].
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element> QuerySelector(string @selector);
    /// <summary>
    /// Returns every descendant matching `selector`.
    ///
    /// Resolves the whole node list with a single `Runtime.getProperties` call
    /// rather than one `evaluate` per match.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element[]> QuerySelectorAll(string @selector);
    /// <summary>
    /// Finds a descendant by attribute value.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element> QuerySelectorAttr(string @attribute, string @value);
    /// <summary>
    /// Finds a descendant matching an XPath expression.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element> QuerySelectorXpath(string @xpath);
    /// <summary>
    /// Captures a PNG screenshot cropped to this element.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<byte[]> Screenshot();
    /// <summary>
    /// Captures a base64 PNG screenshot cropped to this element.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> ScreenshotBase64();
    /// <summary>
    /// Selects options by value or label on this `<select>` element.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task SelectOption(string @valuesJson);
    /// <summary>
    /// Sets the files of this `<input type="file">` element.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task SetInputFiles(string @filesJson);
    /// <summary>
    /// Returns the visible text of the element.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<string> Text();
    /// <exception cref="XcelerateException"></exception>
    Task<Element> TypeText(string @text);
    /// <summary>
    /// Waits for a descendant matching `selector` to appear.
    /// </summary>
    /// <exception cref="XcelerateException"></exception>
    Task<Element> WaitForSelector(string @selector);
}
